def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    dp = [[[float('inf')] * N for _ in range(N)] for _ in range(k + 1)]
    dp[0][0][0] = grid[0][0]

    for step in range(1, k + 1):
        for r in range(N):
            for c in range(N):
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < N and 0 <= nc < N:
                        dp[step][r][c] = min(dp[step][r][c], dp[step - 1][nr][nc] + grid[r][c])

    min_val = float('inf')
    min_path = []
    for r in range(N):
        for c in range(N):
            if dp[k][r][c] < min_val:
                min_val = dp[k][r][c]
                min_path = [grid[r][c]]
                for step in range(1, k):
                    min_val += grid[r][c]
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < N and 0 <= nc < N and dp[step][nr][nc] == dp[step - 1][r][c]:
